import { spawn } from "node:child_process";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { Type } from "typebox";
import { getAgentDir, parseFrontmatter, type ExtensionAPI } from "@earendil-works/pi-coding-agent";
const MAX_PARALLEL_TASKS = 8;
const MAX_CONCURRENCY = 4;
const MAX_OUTPUT_BYTES = 50 * 1024;
const CHILD_FLAGS = ["--mode", "json", "-p", "--no-session", "--no-extensions", "--no-skills", "--no-prompt-templates", "--no-themes", "--no-context-files", "--no-approve"];
type Agent = { name: string; description: string; tools: string[]; prompt: string }; type Outcome = { text: string; failed: boolean };
function serverAgents(): Agent[] { const dir = path.join(getAgentDir(), "agents"); let entries: fs.Dirent[]; try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return []; } return entries.filter((entry) => entry.isFile() && entry.name.endsWith(".md")).flatMap((entry) => { try { const parsed = parseFrontmatter<Record<string, string>>(fs.readFileSync(path.join(dir, entry.name), "utf8")); const name = parsed.frontmatter.name?.trim(); const description = parsed.frontmatter.description?.trim(); if (!name || !description) return []; return [{ name, description, tools: (parsed.frontmatter.tools ?? "").split(",").map((value) => value.trim()).filter(Boolean), prompt: parsed.body }]; } catch { return []; } }); }
function invocation(args: string[]) { const script = process.argv[1]; if (script && !script.startsWith("/$bunfs/root/") && fs.existsSync(script)) return { command: process.execPath, args: [script, ...args] }; return { command: "pi", args }; }
function limit(value: string) { return Buffer.byteLength(value) <= MAX_OUTPUT_BYTES ? value : Buffer.from(value).subarray(0, MAX_OUTPUT_BYTES).toString() + "\n[output truncated]"; }
function finalAnswer(output: string) { let answer = ""; for (const line of output.split(/\r?\n/)) { try { const event = JSON.parse(line); const message = event.message ?? event; if (message?.role === "assistant") { const content = Array.isArray(message.content) ? message.content.map((part: any) => part.text ?? "").join("") : message.content; if (typeof content === "string" && content.trim()) answer = content; } } catch {} } return answer || output; }
async function run(agent: Agent, task: string, cwd: string, signal?: AbortSignal): Promise<Outcome> { const model = process.env.DIREXTALK_WORKER_MODEL?.trim(); if (!model) return { text: "subagent failed: worker model unavailable", failed: true }; let promptDir = ""; try { const args = [...CHILD_FLAGS, "--provider", "dirextalk-worker", "--model", model, "--thinking", "medium"]; if (agent.tools.length) args.push("--tools", agent.tools.join(",")); if (agent.prompt.trim()) { promptDir = fs.mkdtempSync(path.join(os.tmpdir(), "dirextalk-subagent-")); const promptPath = path.join(promptDir, "system-prompt.md"); fs.writeFileSync(promptPath, agent.prompt, { mode: 0o600 }); args.push("--append-system-prompt", promptPath); } args.push(`Task: ${task}`); return await new Promise((resolve) => { const call = invocation(args); const child = spawn(call.command, call.args, { cwd, shell: false, stdio: ["ignore", "pipe", "pipe"] }); let output = "", killer: NodeJS.Timeout | undefined; const append = (chunk: Buffer) => { if (Buffer.byteLength(output) < MAX_OUTPUT_BYTES) output = limit(output + chunk.toString()); }; child.stdout.on("data", append); child.stderr.on("data", append); const abort = () => { child.kill("SIGTERM"); killer = setTimeout(() => child.kill("SIGKILL"), 5000); }; if (signal) signal.addEventListener("abort", abort, { once: true }); child.on("close", (code) => { if (killer) clearTimeout(killer); if (signal) signal.removeEventListener("abort", abort); const text = limit(finalAnswer(output)); resolve({ text: code === 0 && !signal?.aborted ? text : `subagent failed: ${text}`, failed: code !== 0 || !!signal?.aborted }); }); child.on("error", () => resolve({ text: "subagent failed", failed: true })); }); } finally { if (promptDir) fs.rmSync(promptDir, { recursive: true, force: true }); } }
async function bounded<T>(items: T[], fn: (item: T) => Promise<Outcome>): Promise<Outcome[]> { const results = new Array<Outcome>(items.length); let next = 0; await Promise.all(new Array(Math.min(MAX_CONCURRENCY, items.length)).fill(null).map(async () => { for (;;) { const index = next++; if (index >= items.length) return; results[index] = await fn(items[index]); } })); return results; }
const Item = Type.Object({ agent: Type.String(), task: Type.String(), cwd: Type.Optional(Type.String()) });
export default function (pi: ExtensionAPI) { pi.registerTool({ name: "subagent", label: "Subagent", description: "Run server-owned subagents for independent scopes only; max 8 tasks and 4 concurrent. Project agents are disabled.", parameters: Type.Object({ agent: Type.Optional(Type.String()), task: Type.Optional(Type.String()), cwd: Type.Optional(Type.String()), tasks: Type.Optional(Type.Array(Item, { maxItems: MAX_PARALLEL_TASKS })) }), async execute(_id, params, signal, _update, ctx) { const agents = serverAgents(); const jobs = params.tasks ?? (params.agent && params.task ? [{ agent: params.agent, task: params.task, cwd: params.cwd }] : []); if (!jobs.length || jobs.length > MAX_PARALLEL_TASKS) return { content: [{ type: "text", text: "Provide one task or at most 8 parallel tasks." }], isError: true }; const results = await bounded(jobs, async (job) => { const agent = agents.find((item) => item.name === job.agent); return agent ? run(agent, job.task, job.cwd ? path.resolve(ctx.cwd, job.cwd) : ctx.cwd, signal) : { text: `unknown server agent: ${job.agent}`, failed: true }; }); return { content: [{ type: "text", text: results.map((result) => result.text).join("\n\n---\n\n") }], isError: results.some((result) => result.failed), details: { maxConcurrency: MAX_CONCURRENCY, maxTasks: MAX_PARALLEL_TASKS, serverOwnedAgents: true } }; } }); }
